package com.oyuki.marketsquare.entity; import com.oyuki.user.entity.User; import jakarta.persistence.*; import lombok.*; import java.time.LocalDateTime; @Entity @Table(name="handover_records") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder public class HandoverRecord { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @OneToOne(optional=false) @JoinColumn(name="procurement_id",unique=true) private ProcurementRequest procurement; @ManyToOne(optional=false) @JoinColumn(name="agent_id") private User agent; @ManyToOne(optional=false) @JoinColumn(name="rider_id") private User rider; private String pickupCode; private Integer packageCount; private boolean agentConfirmed; private boolean riderConfirmed; private LocalDateTime handedOverAt; }